#!/usr/bin/env bash
### Script: scripts/local/analysis/14.Run_Full_OSCA_5Geno_5ExprPC.sh
### Purpose: Run one complete full-data cis-eQTL OSCA GLM analysis with only
###          genetic PCs 1-5 and expression PCs 1-5 as quantitative covariates.
### Inputs:
###  - data/processed/geno/plink/Div639_maf0.05 (PLINK files; generated by
###    scripts/local/procesing/15.Make_Full_MAF0.05_Plink.sh)
###  - data/processed/osca/WiDiv631 (BOD files)
###  - data/processed/osca/WiDiv631_PC_5Geno_5Expr.txt
### Output:
###  - results/full/osca/full_5Geno_5ExprPC/cis2Mb.*
### Usage: bash scripts/local/analysis/14.Run_Full_OSCA_5Geno_5ExprPC.sh
### Prerequisites: conda environment 'mkl'; OSCA at ../../soft/osca/osca

set -euo pipefail

# Work from the repository root so project-relative paths remain valid.
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "${SCRIPT_DIR}/../../.."

source "$(conda info --base)/etc/profile.d/conda.sh"
conda activate mkl
export LD_LIBRARY_PATH="${CONDA_PREFIX}/lib${LD_LIBRARY_PATH:+:${LD_LIBRARY_PATH}}"
# OSCA is distributed as an AppImage. This fallback avoids requiring FUSE,
# which is unavailable in some non-interactive environments.
export APPIMAGE_EXTRACT_AND_RUN="${APPIMAGE_EXTRACT_AND_RUN:-1}"

OSCA="${OSCA:-../../soft/osca/osca}"
THREADS="${OSCA_THREADS:-36}"
GENO_PREFIX="data/processed/geno/plink/Div639_maf0.05"
EXPR_PREFIX="data/processed/osca/WiDiv631"
Q_COVAR="data/processed/osca/WiDiv631_PC_5Geno_5Expr.txt"
OUTPUT_DIR="results/full/osca/full_5Geno_5ExprPC"

if [[ ! -x "${OSCA}" ]]; then
  echo "OSCA executable not found or not executable: ${OSCA}" >&2
  exit 1
fi

for file in \
  "${GENO_PREFIX}.bed" \
  "${GENO_PREFIX}.bim" \
  "${GENO_PREFIX}.fam" \
  "${EXPR_PREFIX}.bod" \
  "${EXPR_PREFIX}.oii" \
  "${EXPR_PREFIX}.opi" \
  "${Q_COVAR}"; do
  if [[ ! -f "${file}" ]]; then
    echo "Missing OSCA input: ${file}" >&2
    exit 1
  fi
done

mkdir -p "${OUTPUT_DIR}"

"${OSCA}" \
  --eqtl \
  --bfile "${GENO_PREFIX}" \
  --befile "${EXPR_PREFIX}" \
  --qcovar "${Q_COVAR}" \
  --thread-num "${THREADS}" \
  --cis \
  --cis-wind 2000 \
  --no-fid \
  --out "${OUTPUT_DIR}/cis2Mb"
